$ErrorActionPreference='Stop';$ProgressPreference='SilentlyContinue'
$base='D:\Claude\swiftright\factory\native\windows\.work\rectangle-r11';$control=Join-Path $base 'control-count20-r3';$run=Join-Path $base 'native\count20-r3';$admission=Join-Path $base 'admission-count20-r3';$producer=Join-Path $base 'producer-count20-r3'
function J([string]$f){if((Get-Item $f).Length -gt 2MB){throw 'JSON bound'};Get-Content -Raw $f|ConvertFrom-Json}
$c=J (Join-Path $control 'config.json');$si=J $c.sourceInputsPath;$co=J (Join-Path $control 'coordinator.json');$t=J (Join-Path $control 'task-result.json')
$release=J (Join-Path $control 'release-supplement.json')
if($co.status -cne 'failed' -or $co.count -ne 20 -or $co.taskParentProof -ne $null -or $release.status -cne 'ownership-released-with-parent-certificate-gap' -or $release.lockReleased -ne $true -or $release.originalParentKernelExitCertificate -ne $false -or $release.allNativeOriginalHandleCertificates -ne $true -or $release.schedulerLastTaskResult -ne 0 -or $t.status -cne 'completed-source-bound-observation' -or $t.memoryReceipt.status -cne 'passed' -or $t.memoryReceipt.activeProcessCount -ne 1 -or $t.memoryReceipt.peakJobMemoryUsedBytes -gt 1073741824){throw 'Count20 diagnostic release rejected'}
if($co.sourceInputsHash -cne $c.sourceInputsHash -or $co.issuedMetadataHash -cne $c.issuedMetadataHash){throw 'Count20 lineage rejected'}
. (Join-Path $base 'overlay-count20-r3\integration-fresh-rectangle-v1.ps1')
. (Join-Path $producer 'support\final-exit-certificate.ps1');. (Join-Path $producer 'dependencies\uia-worker\support\final-exit-certificate.ps1');. (Join-Path $producer 'dependencies\uia-worker\schema.ps1');. (Join-Path $base 'overlay-count20-r3\all-owned-release-rectangle-r1.ps1')
for($n=1;$n -le 20;$n++){$d=Join-Path $run ('native-'+$n.ToString('00'));Assert-RootRectangleAllOwnedRelease $d $c.owner $si.compileReceiptPath $c.compileReceiptHash $si.exeRef.path $c.exeHash $si.sourceHash $producer $si}
$observations=J (Join-Path $run 'native-observation.json');if($observations.Count -ne 20 -or @($observations|Where-Object{$_.hostValid -ne $true -or $_.probeForegroundAtCapture -ne $false -or $_.backgroundPlacementRequested -ne $true}).Count){throw 'Count20 capture validity rejected'}
Add-Type -AssemblyName System.IO.Compression
$zip='D:\Claude\swiftright\.factory-work\hosts\rectangle\export-count20-r3-r2.zip';if(Test-Path $zip){throw 'fresh export required'}
$files=@();$total=0
foreach($group in @(@{name='native';root=$run},@{name='control';root=$control},@{name='admission';root=$admission})){
 foreach($f in Get-ChildItem -LiteralPath $group.root -Recurse -File){if(($f.Attributes -band [IO.FileAttributes]::ReparsePoint) -or $f.Length -gt 4MB){throw 'export file bound'};$total+=$f.Length;if($files.Count -ge 1024 -or $total -gt 16MB){throw 'explicit Count20 export bound'};$rel=$group.name+'/'+$f.FullName.Substring($group.root.Length+1).Replace('\','/');$files+=@{path=$rel;originalPath=$f.FullName;bytes=$f.Length;sha256=(Get-FileHash $f.FullName).Hash.ToLowerInvariant()}}
}
$manifest=Join-Path $control 'export-manifest.json';@{kind='root-rectangle-count20-export-v1';files=$files;totalBytes=$total;count=$files.Count;qualified=$false;parity='held';caseID=$si.caseID;caseHash=$si.caseHash;tupleID=$si.tupleID;sourceInputsHash=$c.sourceInputsHash;issuedMetadataHash=$c.issuedMetadataHash;allNativeOriginalHandleCertificates=$true;originalParentKernelExitCertificate=$false;qualification='held-parent-certificate-gap';lockReleased=$true}|ConvertTo-Json -Depth 12|Set-Content $manifest -Encoding UTF8
$stream=[IO.File]::Open($zip,[IO.FileMode]::CreateNew);$a=[IO.Compression.ZipArchive]::new($stream,[IO.Compression.ZipArchiveMode]::Create,$false)
try{foreach($row in $files){$entry=$a.CreateEntry($row.path);$target=$entry.Open();$source=[IO.File]::OpenRead($row.originalPath);try{$source.CopyTo($target,1048576)}finally{$source.Dispose();$target.Dispose()}};$e=$a.CreateEntry('export-manifest.json');$o=$e.Open();$i=[IO.File]::OpenRead($manifest);try{$i.CopyTo($o,1048576)}finally{$i.Dispose();$o.Dispose()}}finally{$a.Dispose();$stream.Dispose()}
@{status='Count20-diagnostic-exported';zipPath=$zip;zipBytes=(Get-Item $zip).Length;zipSha256=(Get-FileHash $zip).Hash.ToLowerInvariant();files=$files.Count;bytes=$total;lockReleased=$release.lockReleased;originalParentKernelExitCertificate=$false;peakJobMemoryUsedBytes=$t.memoryReceipt.peakJobMemoryUsedBytes}|ConvertTo-Json
